items.push({ json: Object.assign({ kind: 'einzelbild', platform: 'linkedin', format: 'einzelpost', branding_variant: layouts.linkedin.einzelpost.id, photo_credit: fotoCredit, index: 0, file_name: 'einzelbild.png', path: k.kuerzel + '/' + paket.post_id + '/einzelbild.png', html_chars: ebHtml.length }, basisJson), binary: { index_html: ebBin }, pairedItem: { item: 0 } });
