// Zweck: aus jedem Abbruch (E5, F6, F3, F5, F8) genau eine Protokollzeile mit Stelle fehlerweg bauen, nur Metadaten.
// Warum seit v05 nur Abbrueche: Ersatzwege (F1, F2, F3 Ersatzmodell, F4, F7) stehen in der Protokollzeile am Ende.
// Warum einmal fuer alle Elemente (v02): kommen mehrere Fehler-Elemente an (Bild hochladen je Bild), entsteht trotzdem nur eine Zeile.
const k = $('Konfiguration und Startzeit [Edit Fields]').first().json;
const ein = $input.first().json;
const lief = n => { try { return $(n).isExecuted === true; } catch (e) { return false; } };
// Warum all(i): Ausgang 0 ist das Ergebnis, Ausgang 1 der Fehlerausgang mit der Fehlermeldung.
const ausgang = (n, i) => { try { return $(n).all(i) || []; } catch (e) { return []; } };
const fehlerVon = n => { const it = ausgang(n, 1)[0]; const e = it && it.json && it.json.error; return e ? String(e.message || e).slice(0, 160) : ''; };
let post = null;
if (lief('Post anlegen [Supabase]')) post = $('Post anlegen [Supabase]').first().json.id || null;
// Warum diese Liste (v02): nach dem bezahlten Modellaufruf darf kein Abbruch mehr ohne Zeile enden; F8 = Abbruch nach dem Modellaufruf.
const nachModell = ['Paket prüfen [Code]', 'Logo laden [HTTP Request]', 'Bild hochladen [HTTP Request]', 'Post speichern [HTTP Request]', 'Signierte Adressen holen [HTTP Request]', 'Bild laden [HTTP Request]'];
const abbruch = nachModell.find(n => lief(n) && ausgang(n, 1).length > 0);
let text;
// Warum am gelaufenen Knoten erkannt: F5 und F3 kommen ohne eigenen Vermerkknoten an (v05).
if (lief('Nur Texte speichern [HTTP Request]')) text = 'F5: Rendern fehlgeschlagen (' + (fehlerVon('Bild rendern [HTTP Request]') || 'Render-Dienst nicht erreichbar') + '), Post nur mit Texten (nur_texte)';
else if (abbruch) text = 'F8: Abbruch nach dem Modellaufruf in ' + abbruch.replace(/ \[[^\]]*\]$/, '') + ' (' + (fehlerVon(abbruch) || 'ohne Meldung') + ')';
else if (lief('Status fehler setzen [Supabase]')) text = 'F3: Hauptmodell und Ersatzmodell ohne gültiges Paket (' + (fehlerVon('Ersatzpaket schreiben [Basic LLM Chain]') || 'unbekannt') + ')';
else text = String(ein.error_text || 'Abbruch ohne Text');
// Warum: bricht der Lauf ab, laeuft die Protokollzeile am Ende nicht mehr, deshalb stehen fruehere Ersatzwege hier mit.
const ppOk = ausgang('Paket prüfen [Code]', 0);
const pp = ppOk.length ? ppOk[0].json : null;
const nvLief = ausgang('Ersatzpaket schreiben [Basic LLM Chain]', 0).length > 0 || ausgang('Ersatzpaket schreiben [Basic LLM Chain]', 1).length > 0;
const frueher = [];
if (lief('Quelle-Fallback F1 [Edit Fields]')) frueher.push('F1');
if (lief('Video-Fallback F2 [Edit Fields]')) frueher.push('F2');
if ((pp && pp.fallback_model_used) || (!pp && nvLief && !lief('Status fehler setzen [Supabase]'))) frueher.push('F3 Ersatzmodell');
const rl = ausgang('Render-Liste bauen [Code]', 0);
if (rl.length && rl[0].json.image_source !== 'flux') frueher.push('F4');
const zeile = {
  workflow_name: k.workflow_name,
  execution_id: k.execution_id,
  trace_id: k.trace_id,
  prompt_version: k.prompt_version,
  execution_mode: k.execution_mode,
  stage: 'fehlerweg',
  status: 'fehler',
  duration_ms: Math.round(Date.now() - new Date(k.start_time).getTime()),
  model: nvLief ? 'nvidia/nemotron-3-super-120b-a12b' : k.model_primary,
  customer_code: k.customer_code
};
// Warum ohne post_id bei E5 und F6: vor dem Anlegen des Posts gibt es keine UUID, ein leerer Wert waere fuer die Spalte ungueltig.
if (post) zeile.post_id = post;
// Warum: auch ein Abbruch nach einem bezahlten Modellaufruf traegt Tokens und Kosten, fehlende Kosten bleiben null mit Vermerk.
const vermerk = [];
if (pp) {
  zeile.model = pp.model_used; zeile.prompt_tokens = pp.prompt_tokens; zeile.completion_tokens = pp.completion_tokens; zeile.total_tokens = pp.total_tokens; zeile.cost_usd = pp.cost_usd;
  if (pp.cost_note) vermerk.push(pp.cost_note);
} else if (lief('Tokens und Kosten erfassen [Code]')) {
  // Warum aus dem Kostenknoten (v03): er laeuft auf beiden Wegen (Antwort und Fehlerausgang), auch wenn danach beide Modelle scheitern.
  const kq = $('Tokens und Kosten erfassen [Code]').first().json;
  zeile.prompt_tokens = kq.prompt_tokens;
  zeile.completion_tokens = kq.completion_tokens;
  zeile.total_tokens = kq.total_tokens;
  zeile.cost_usd = kq.cost_usd;
  if (kq.cost_note) vermerk.push(kq.cost_note);
  if (nvLief) vermerk.push('NVIDIA-Tokens nicht lesbar');
}
if (vermerk.length) text += ' | ' + vermerk.join('; ');
if (frueher.length) text += ' | vorher im Lauf: ' + frueher.join(', ');
zeile.error_text = text.slice(0, 300);
return [{ json: zeile }];

// Warum: Das Telegram-Album (sendMediaGroup) nimmt keine Bilderliste aus einem Ausdruck an,
// n8n hat den Ausdruck beim Speichern verworfen (Lauf 664, media leer). Deshalb ein Element je Bild,
// der folgende Knoten schickt jedes Bild einzeln.
const basis = $('Konfiguration und Startzeit [Edit Fields]').first().json.supabase_url + '/storage/v1';
const liste = ($json.body || []).filter(x => x.signedURL);
if (liste.length === 0) {
  throw new Error('Keine signierten Bildadressen erhalten, Vorschau nicht moeglich.');
}
// Warum generated_at (12.10.2026, Verbesserung 6 aus Lauf 697): die Laufzeit bis zur fertigen Vorschau getrennt von der Wartezeit auf die Freigabe messen.
const fertig = new Date().toISOString();
return liste.map((x, i) => ({
  json: { url: basis + x.signedURL, index: i + 1, total: liste.length, file_name: x.path.split('/').pop(), generated_at: fertig }
}));

// Zweck: genau eine Protokollzeile am Ende des Laufs bauen, mit allen Ersatzwegen dieses Laufs, nur Metadaten.
// Warum ein Knoten statt Linien in den Fehlerweg: jeder Ersatzweg braucht eine Spur, aber keine eigene Linie quer ueber die Leinwand (v05).
const k = $('Konfiguration und Startzeit [Edit Fields]').first().json;
const p = $('Paket prüfen [Code]').first().json;
const r = $('Render-Liste bauen [Code]').first().json;
const lief = n => { try { return $(n).isExecuted === true; } catch (e) { return false; } };
const einst = $('Einstellungen laden [HTTP Request]').first().json.body || [];
const wert = s => (einst.find(z => z.setting_key === s) || {}).setting_value || '';
const ersatz = [];
if (lief('Quelle-Fallback F1 [Edit Fields]')) ersatz.push($('Quelle-Fallback F1 [Edit Fields]').first().json.error_text);
if (lief('Video-Fallback F2 [Edit Fields]')) ersatz.push($('Video-Fallback F2 [Edit Fields]').first().json.error_text);
// Warum ueber Paket pruefen: es merkt sich, ob die Chain auf das Ersatzmodell umgeschaltet hat (F3).
if (p.fallback_model_used) ersatz.push('F3: Hauptmodell ausgefallen, Paket vom Ersatzmodell NVIDIA');
// Warum (12.10.2026): die Sonar-Recherche ist ein Zusatz; scheitert sie, ist das ein Ersatzweg mit Spur, ihre Kosten zaehlen zum Lauf.
const rs = lief('Recherche auswerten [Code]') ? $('Recherche auswerten [Code]').first().json : null;
// Warum nur fallback (12.10.2026): uebersprungene Fakten-Recherche (Artikel, Video, eigener Text) ist kein Ersatzweg; eine gescheiterte Vorlagen-Recherche schon.
if (rs && rs.research_status === 'fallback') ersatz.push(rs.research_note);
if (rs && rs.viral_status === 'fehler') ersatz.push(rs.viral_note);
// Warum ueber Render-Liste bauen: sie erkennt selbst, ob ein FLUX-Bild kam (F4).
// Warum aufgeteilt (10.10.2026): ohne Suchbegriff liefert die Fotosuche keinen Treffer (Foto suchen aus oder photo_query leer). Dieser Hinweis ist kein Ersatzweg und macht den Lauf nicht zum fallback.
const fotoFrage = lief('Branding-Variante wählen [Code]') ? String($('Branding-Variante wählen [Code]').first().json.photo_query || '') : '';
const bildNurHinweis = [];
for (const t of String(r.image_note || '').split('; ').filter(Boolean)) {
  if (!fotoFrage && t.startsWith('Pixabay ohne nutzbaren Treffer')) bildNurHinweis.push(t); else ersatz.push(t);
}
// Warum F7 hier: die Frist laeuft im Telegram-Knoten ab, ohne Antwort fehlt data.approved bzw. data.text.
if (lief('Freigabe abwarten [Telegram]')) {
  const d = $('Freigabe abwarten [Telegram]').first().json.data;
  if (!d || d.approved === undefined) ersatz.push('F7: Freigabe-Frist 24 Stunden abgelaufen, Status freigabe_abgelaufen');
  else if (lief('Grund abfragen [Telegram]')) { const g = $('Grund abfragen [Telegram]').first().json.data; if (!g || !g.text) ersatz.push('F7: Frist für den Ablehnungsgrund (2 Stunden) abgelaufen, Status abgelehnt ohne Grund'); }
}
const hinweise = ersatz.concat(bildNurHinweis);
if (rs && rs.viral_status === 'keine') hinweise.push(rs.viral_note);
for (const q of (p.quality_notes || [])) hinweise.push('Q: ' + q);
// Warum: unbekannte Kosten oder Tokens stehen als Vermerk in error_text, die Spalte bleibt null.
if (p.cost_note) hinweise.push(p.cost_note);
if (!(wert('telegram_chat_id') && wert('telegram_freigabe_nutzer_id'))) hinweise.push('Telegram übersprungen: Chat-ID oder Freigabe-Nutzer-ID fehlt, Status bleibt wartet_auf_freigabe');
return [{ json: {
  workflow_name: k.workflow_name, execution_id: k.execution_id, trace_id: k.trace_id, prompt_version: k.prompt_version, execution_mode: k.execution_mode,
  stage: 'ende', status: ersatz.length ? 'fallback' : 'ok',
  duration_ms: Math.round(Date.now() - new Date(k.start_time).getTime()),
  // Warum getrennt (Verbesserung 6 aus Lauf 697): duration_ms enthaelt die Wartezeit auf die Freigabe, generation_ms nur die Erzeugung bis zur Vorschau.
  generation_ms: lief('Bilder einzeln [Code]') ? Math.round(new Date($('Bilder einzeln [Code]').first().json.generated_at).getTime() - new Date(k.start_time).getTime()) : null,
  model: p.model_used, customer_code: (p.customer || {}).kuerzel, post_id: p.post_id,
  error_text: hinweise.join('; ').slice(0, 300),
  // Warum: Tokens und Kosten aus Paket pruefen, Quelle steht dort in token_source.
  prompt_tokens: p.prompt_tokens, completion_tokens: p.completion_tokens, total_tokens: p.total_tokens, cost_usd: p.cost_usd == null ? null : Math.round((p.cost_usd + ((rs && rs.research_cost_usd) || 0)) * 1e7) / 1e7
} }];

// Zweck: Antwort von OpenRouter in das bisherige Paketformat bringen und gegen das Schema von K1 v05 pruefen. Tokens und Kosten erfasst seit v03 der Knoten davor.
const k = $input.first().json;
const cfg = $('Konfiguration und Startzeit [Edit Fields]').first().json;
// Warum Wurf ohne Antwort: Zeitlimit oder HTTP-Fehler, die Kostenerfassung hat den Vermerk schon; der Fehlerausgang fuehrt zum Ersatzmodell NVIDIA (F3).
if (!k.response_present) throw new Error('OpenRouter ohne Antwort (' + (k.openrouter_error || 'ohne Meldung') + ')');
const r = k.openrouter_response || {};
const wahl = (r.choices || [])[0] || {};
const inhalt = String((wahl.message || {}).content || '');
// Warum Codeblock entfernen: manche Modelle setzen das JSON trotz Vorgabe zwischen drei Backticks.
const roh = inhalt.replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '');
let paket;
try { paket = JSON.parse(roh); } catch (e) { throw new Error('Antwort ist kein gültiges JSON (finish_reason ' + (wahl.finish_reason || 'unbekannt') + ')'); }
if (!paket || typeof paket !== 'object' || Array.isArray(paket)) throw new Error('Antwort ist kein JSON-Objekt');
// Warum Testschalter: (07.10.2026) laesst sich nur mit einem zu kurzen Paket nachweisen; 'lesen' kuerzt hier auf 4 Folien, Standard 'aus'.
if (cfg.test_truncate_slides === 'lesen' && Array.isArray(paket.slides)) paket.slides = paket.slides.slice(0, 4);
// Warum hier pruefen: dieselben Grenzen wie der Structured Output Parser in K1 v05, ein Verstoss geht ueber den Fehlerausgang zum Ersatzmodell (F3).
const pflicht = ['slides', 'caption_instagram', 'hashtags', 'linkedin_post', 'image_prompt'];
const fehlt = pflicht.filter(f => paket[f] === undefined);
if (fehlt.length) throw new Error('Paket ohne Pflichtfelder: ' + fehlt.join(', '));
const verstoss = [];
if (!Array.isArray(paket.slides)) verstoss.push('slides ist keine Liste');
else {
  // Warum 5 bis 8: minItems und maxItems im Parser-Schema von K1 v05 (G9).
  if (paket.slides.length < 5 || paket.slides.length > 8) verstoss.push(paket.slides.length + ' Folien statt 5 bis 8');
  paket.slides.forEach((f, i) => {
    if (!f || typeof f !== 'object') { verstoss.push('Folie ' + (i + 1) + ' ist kein Objekt'); return; }
    if (!['titel', 'inhalt', 'abschluss'].includes(f.type)) verstoss.push('Folie ' + (i + 1) + ' mit unbekanntem type');
    if (typeof f.heading !== 'string' || typeof f.text !== 'string') verstoss.push('Folie ' + (i + 1) + ' ohne Überschrift oder Text als Zeichenkette');
  });
  // Warum zusaetzlich: Paket pruefen verwirft leere Folien, danach duerfen es nicht weniger als 5 sein.
  const gefuellt = paket.slides.filter(f => f && (f.heading || f.text)).length;
  if (gefuellt < 5 && paket.slides.length >= 5) verstoss.push('nur ' + gefuellt + ' gefüllte Folien');
}
for (const f of ['caption_instagram', 'linkedin_post', 'image_prompt']) if (typeof paket[f] !== 'string') verstoss.push(f + ' ist keine Zeichenkette');
if (!Array.isArray(paket.hashtags) || paket.hashtags.some(t => typeof t !== 'string')) verstoss.push('hashtags ist keine Liste aus Zeichenketten');
if (verstoss.length) throw new Error('Paket verletzt das Schema: ' + verstoss.join('; '));
return [{ json: { output: paket, model_response: k.model_response } }];

// Zweck: Tokens und Kosten des OpenRouter-Aufrufs erfassen, als eigener sichtbarer Schritt direkt hinter dem HTTP-Knoten (W04T04 Punkt 3).
// Warum beide Ausgaenge hier ankommen: auch der Ersatzweg NVIDIA laeuft durch diese Kostenerfassung, damit ein Ausfall sichtbar null mit Vermerk schreibt, nie 0.
// Warum kein Wurf: der Knoten steht nach dem bezahlten Aufruf, ein Fehler hier darf die Antwort nicht verlieren; Probleme landen im Vermerk.
const zahl = v => (typeof v === 'number' && isFinite(v)) ? v : null;
const vermerk = [];
let r = {};
let antwortDa = false, usageDa = false;
let tok = { prompt_tokens: null, completion_tokens: null, total_tokens: null, cost_usd: null };
let fehlerText = '';
try {
  r = ($input.first() || {}).json || {};
  // Warum choices als Kennzeichen der Antwort: nur eine echte Antwort von OpenRouter traegt choices, der Fehlerausgang traegt error.
  antwortDa = Array.isArray(r.choices);
  // Warum usage unabhaengig von choices: liefert OpenRouter usage ohne choices, sind die Kosten trotzdem angefallen und bekannt.
  const u = (r.usage && typeof r.usage === 'object') ? r.usage : null;
  usageDa = !!u;
  if (u) {
    // Warum usage.cost: OpenRouter liefert die Kosten in USD fertig mit, keine Preistabelle, die still veraltet.
    tok = { prompt_tokens: zahl(u.prompt_tokens), completion_tokens: zahl(u.completion_tokens), total_tokens: zahl(u.total_tokens), cost_usd: zahl(u.cost) };
    // Warum kein 0: fehlt usage.cost, ist der Preis unbekannt, nicht kostenlos.
    if (tok.cost_usd === null) vermerk.push('Kosten unbekannt: OpenRouter-Antwort ohne usage.cost');
    if (tok.total_tokens === null) vermerk.push('Tokens unbekannt: OpenRouter-Antwort ohne usage');
  } else if (antwortDa) {
    vermerk.push('Kosten unbekannt: OpenRouter-Antwort ohne usage.cost');
    vermerk.push('Tokens unbekannt: OpenRouter-Antwort ohne usage');
  } else {
    // Warum unbekannt statt 0: ein Zeitlimit beweist nur, dass keine Antwort kam, nicht dass nichts abgerechnet wurde.
    vermerk.push('Kosten unbekannt: OpenRouter ohne Antwort (Zeitlimit oder Fehler), Abrechnung nicht messbar');
  }
  if (!antwortDa) {
    // Warum Zeichenkette zulassen: der HTTP-Knoten liefert den Fehler teils als Text, teils als Objekt mit Ursache.
    const e = r.error;
    const teile = typeof e === 'string' ? [e] : (e && typeof e === 'object') ? [e.message || e.description, e.cause && e.cause.message] : [];
    fehlerText = (teile.filter(Boolean).join(', ') || (usageDa ? 'Antwort ohne choices' : 'Fehlerausgang ohne Meldung')).slice(0, 160);
  }
} catch (e) {
  vermerk.push('Kostenerfassung fehlgeschlagen: ' + String(e.message || e).slice(0, 120));
}
return [{ json: {
  response_present: antwortDa,
  usage_present: usageDa,
  openrouter_response: antwortDa ? r : null,
  openrouter_error: fehlerText,
  model_response: antwortDa ? (r.model || '') : '',
  prompt_tokens: tok.prompt_tokens,
  completion_tokens: tok.completion_tokens,
  total_tokens: tok.total_tokens,
  cost_usd: tok.cost_usd,
  token_source: usageDa ? 'openrouter usage' : 'ohne openrouter usage',
  cost_note: vermerk.join('; ')
} }];

// 1 Kunde und 1 Paket je Auftrag. photo_query und process_steps kommen seit 10.10.2026 bereinigt aus Paket pruefen.
const paket = $('Paket prüfen [Code]').first().json;
const row = $input.first().json;
if (!row || row.kuerzel !== paket.customer?.kuerzel) throw new Error('Branding-Kunde fehlt oder passt nicht zum Auftrag.');
// Platzhalter aus dem eigenen Kundenprofil (Farben, Schriften, Logo), Entscheidung vom 10.10.2026. Greift nur, wenn branding_pack leer ist.
const pk = paket.customer || {};
const farbe = (v, d) => (/^#[0-9a-fA-F]{6}$/.test(v || '') ? v : d);
const standard = {version: 1, status: 'platzhalter', markenname: pk.name || 'Kunde',
  logo: {modus: 'datei', pfad: pk.logo_url || '', text: pk.name || ''},
  schriften: {titel: pk.schrift_titel || 'DejaVu Sans', text: pk.schrift_text || 'DejaVu Sans'},
  farben: {primaer: farbe(pk.farbe_primaer, '#15774E'), sekundaer: farbe(pk.farbe_sekundaer, '#515F56'), akzent: farbe(pk.farbe_akzent, '#22A26F'), hintergrund: farbe(pk.farbe_hintergrund, '#F4FBF7'), text: farbe(pk.farbe_text, '#111C16')},
  postformen: ['hybrid_personen', 'thema', 'ablauf'],
  austauschstellen: ['markenname', 'logo', 'schriften', 'farben', 'postformen', 'layouts'],
  layouts: {"instagram": {"karussell": [{"id": "instagram_karussell_1", "stil": "hybrid_personen", "postform": "hybrid_personen"}, {"id": "instagram_karussell_2", "stil": "thema", "postform": "thema"}, {"id": "instagram_karussell_3", "stil": "ablauf", "postform": "ablauf"}], "einzelpost": [{"id": "instagram_einzelpost_1", "stil": "hybrid_personen", "postform": "hybrid_personen"}, {"id": "instagram_einzelpost_2", "stil": "thema", "postform": "thema"}, {"id": "instagram_einzelpost_3", "stil": "ablauf", "postform": "ablauf"}]}, "linkedin": {"karussell": [{"id": "linkedin_karussell_1", "stil": "hybrid_personen", "postform": "hybrid_personen"}, {"id": "linkedin_karussell_2", "stil": "thema", "postform": "thema"}, {"id": "linkedin_karussell_3", "stil": "ablauf", "postform": "ablauf"}], "einzelpost": [{"id": "linkedin_einzelpost_1", "stil": "hybrid_personen", "postform": "hybrid_personen"}, {"id": "linkedin_einzelpost_2", "stil": "thema", "postform": "thema"}, {"id": "linkedin_einzelpost_3", "stil": "ablauf", "postform": "ablauf"}]}}};
let b = row.branding_pack;
if (typeof b === 'string') b = JSON.parse(b);
if (b == null) b = standard;
if (typeof b !== 'object' || Array.isArray(b)) throw new Error('branding_pack muss ein JSON-Objekt sein.');
b = {...standard, ...b, logo: {...standard.logo, ...b.logo}, schriften: {...standard.schriften, ...b.schriften}, farben: {...standard.farben, ...b.farben}};
const kunde = {...paket.customer, name: b.markenname};
for (const [key, value] of Object.entries(b.farben)) {
  if (!/^#[0-9a-fA-F]{6}$/.test(value)) throw new Error('Ungueltige Branding-Farbe: ' + key);
  kunde['farbe_' + key] = value;
}
kunde.schrift_titel = b.schriften.titel;
kunde.schrift_text = b.schriften.text;
const varianten = {};
for (const plattform of ['instagram', 'linkedin']) {
  varianten[plattform] = {};
  for (const format of ['karussell', 'einzelpost']) {
    const liste = b.layouts?.[plattform]?.[format];
    if (!Array.isArray(liste) || liste.length < 3 || liste.length > 5) throw new Error('3 bis 5 Layouts verlangt: ' + plattform + '/' + format);
    const postform = paket.process_steps?.length ? 'ablauf' : (paket.postform || 'hybrid_personen');
    const variante = liste.find(v => v.postform === postform) || liste[0];
    if (!variante.id || !['hybrid_personen', 'thema', 'ablauf'].includes(variante.stil)) throw new Error('Layout-ID oder Stil ungueltig.');
    varianten[plattform][format] = variante;
  }
}
const cfg = $('Konfiguration und Startzeit [Edit Fields]').first().json;
const plattform = String(paket.platform || cfg.platform || 'instagram').toLowerCase();
const format = String(paket.format || cfg.format || 'karussell').toLowerCase();
if (!varianten[plattform]?.[format]) throw new Error('Unbekannte Plattform oder unbekanntes Format.');
return [{json: {...paket, customer: kunde, branding_pack: b, branding_variants: varianten,
  branding_variant: varianten[plattform][format].id, platform: plattform, format,
  branding_note: b.status === 'platzhalter' ? 'Platzhalter-Branding aus dem Kundenprofil, Austauschstellen im branding_pack.' : '',
  photo_query: String(paket.photo_query || '').trim()}, pairedItem: {item: 0}}];

// Auth-, Timeout- und Leerantworten fuehren sichtbar zum vorhandenen FLUX-Weg.
// Warum Pixabay (10.10.2026): Pexels stellt keine neuen API-Schluessel mehr aus. Treffer stehen in body.hits, das Bild in largeImageURL (hoechstens 1280 px).
const basis = $('Branding-Variante wählen [Code]').first().json;
const r = $input.first().json;
const body = r.body || r;
const hits = Array.isArray(body.hits) ? body.hits : [];
// Warum der Suchbegriff geprueft wird: ohne q liefert Pixabay beliebte Bilder statt eines passenden Fotos.
const frage = String(basis.photo_query || '').trim();
// Warum Muster statt new URL: im Code-Knoten dieser Instanz verwarf new URL alle 5 echten Treffer (Hilfsaufruf 733). Das Muster laesst nur https://pixabay.com/ bzw. https://cdn.pixabay.com/ ohne Port und Zugangsdaten zu.
const safePhoto = s => typeof s === 'string' && /^https:\/\/(cdn\.)?pixabay\.com\/[^\s"'<>]*$/.test(s);
const safeLink = s => typeof s === 'string' && /^https:\/\/(www\.)?pixabay\.com\/[^\s"'<>]*$/.test(s);
// Warum Bewertung nach Schlagwoertern (12.10.2026, Lauf 763): Pixabay sortiert nach Beliebtheit, der erste Treffer zu "team whiteboard" war ein Hund. Gewaehlt wird der Treffer, dessen Schlagwoerter die meisten Suchwoerter enthalten.
const woerter = frage.toLowerCase().split(/\s+/).filter(x => x.length > 2);
const wert = h => { const t = String(h.tags || '').toLowerCase(); let a = 0, b = 0; for (const x of woerter) { const n = t.split(x).length - 1; if (n) { a++; b += n; } } return a * 100 + b; };
const p = frage ? hits.filter(h => safePhoto(h.largeImageURL) && safeLink(h.pageURL)).map((h, i) => ({h, s: wert(h), i})).sort((x, y) => y.s - x.s || x.i - y.i).map(x => x.h)[0] || null : null;
const status = Number(r.statusCode || 200);
const ok = !r.error && status >= 200 && status < 300 && !!p;
// Warum Herkunft mitgeben: Pixabay verlangt, dass die Quelle sichtbar ist; Render-Liste bauen schreibt sie aufs Bild.
const nutzerUrl = ok && safeLink(p.userURL) ? p.userURL : '';
return [{json: {...basis, photo_ok: ok, photo_url: ok ? p.largeImageURL : '',
  photo_credit: ok ? {photographer: String(p.user || ''), photographer_url: nutzerUrl, source: 'Pixabay', pixabay_url: p.pageURL, photo_id: p.id} : null,
  photo_note: ok ? '' : (r.error ? 'Pixabay-Anfrage gescheitert, weiter mit FLUX.' : 'Pixabay ohne nutzbaren Treffer (Status ' + status + ', ' + hits.length + ' Treffer), weiter mit FLUX.')}, pairedItem: {item: 0}}];

// Binaere Speichermodi ueber den n8n-Helper lesen, kein direkter Zugriff auf binary.data.
const basis = $('Foto auswerten [Code]').first().json;
const item = $input.first();
if (!item.binary?.foto) throw new Error('Foto-Download hat keine Binaerdatei geliefert.');
const buffer = await this.helpers.getBinaryDataBuffer(0, 'foto');
const jpeg = buffer.length > 3 && buffer[0] === 255 && buffer[1] === 216 && buffer[2] === 255;
const png = buffer.length > 8 && buffer.subarray(0, 8).equals(Buffer.from([137,80,78,71,13,10,26,10]));
if ((!jpeg && !png) || buffer.length > 12 * 1024 * 1024) throw new Error('Foto ist kein JPEG/PNG oder groesser als 12 MiB.');
return [{json: {...basis, photo_data_uri: 'data:' + (png ? 'image/png' : 'image/jpeg') + ';base64,' + buffer.toString('base64')}, pairedItem: {item: 0}}];

// Fehlerausgaenge koennen den Prompt verlieren. Validierten Kontext gezielt wiederherstellen.
const basis = $('Branding-Variante wählen [Code]').first().json;
const fehler = $input.first().json;
return [{json: {...basis, photo_ok: false, photo_url: '', photo_data_uri: '', photo_credit: null,
  photo_note: 'Pixabay-Fotopfad gescheitert, Kontext wiederhergestellt, weiter mit FLUX.',
  photo_error: String(fehler.error?.message || fehler.message || 'Foto konnte nicht verarbeitet werden.').slice(0, 240)}, pairedItem: {item: 0}}];

// Zweck: zwei Sonar-Antworten auswerten: (1) belegte Fakten, nur bei Thema, Research und unbekannter Quellenart,
// (2) aktuelle englische Posts der letzten 7 Tage mit Hook, Hashtags und Keywords, bei jedem Post (Abgleich mit echten Beiträgen).
// Warum kein Wurf: beide Recherchen sind ein Zusatz. Scheitert eine, laeuft das Paket weiter und die Protokollzeile vermerkt es.
const lief = n => { try { return $(n).isExecuted === true; } catch (e) { return false; } };
const zahl = v => (typeof v === 'number' && isFinite(v)) ? v : null;
const nimm = n => { try { const a = $(n).all(0); if (a.length) return a[0].json; const b = $(n).all(1); return b.length ? b[0].json : {}; } catch (e) { return { error: { message: 'Knoten ' + n + ' nicht lesbar: ' + e.message } }; } };

// ---------- Teil 1: Fakten (nur wenn Recherche Sonar lief) ----------
let fakt = { research_status: 'uebersprungen', research_text: '', research_sources: [], research_model: 'perplexity/sonar', research_tokens: null, research_fact_cost_usd: null, research_note: '' };
if (lief('Recherche Sonar [HTTP Request]')) {
  const r = ($input.first() || {}).json || {};
  const wahl = (Array.isArray(r.choices) ? r.choices : [])[0] || {};
  const msg = wahl.message || {};
  const text = String(msg.content || '').trim();
  // Warum zuerst die Adressen im Text: nur sie stehen hinter einer Aussage. annotations und citations enthalten auch unbenutzte Treffer (Hilfsaufrufe 754 bis 759).
  const urls = [];
  const add = u => { u = String(u || '').trim().replace(/[)\].,;]+$/, ''); if (/^https?:\/\/[^\s<>"']+$/.test(u) && !urls.includes(u)) urls.push(u); };
  for (const m of text.match(/https?:\/\/[^\s<>"')\]]+/g) || []) add(m);
  if (!urls.length) {
    for (const a of (Array.isArray(msg.annotations) ? msg.annotations : [])) add(a && (a.url_citation ? a.url_citation.url : a.url));
    for (const c of (Array.isArray(r.citations) ? r.citations : [])) add(typeof c === 'string' ? c : c && c.url);
  }
  const u = (r.usage && typeof r.usage === 'object') ? r.usage : {};
  const fehler = r.error ? String(r.error.message || r.error).slice(0, 160) : '';
  const keine = /KEINE BELEGTEN QUELLEN/i.test(text);
  // Warum mindestens 1 Adresse: ohne Beleg ist die Recherche nichts wert, das Paket bleibt dann beim bisherigen Weg (keine erfundenen Studien).
  const ok = !fehler && !keine && text.length >= 80 && urls.length >= 1;
  fakt = { research_status: ok ? 'ok' : 'fallback', research_text: ok ? text.replace(/\[(\d+)\]/g, '').slice(0, 2500) : '', research_sources: ok ? urls.slice(0, 8) : [],
    research_model: String(r.model || 'perplexity/sonar'), research_tokens: zahl(u.total_tokens), research_fact_cost_usd: zahl(u.cost),
    research_note: ok ? '' : ('R1: Recherche ohne verwertbares Ergebnis (' + (fehler || (keine ? 'Sonar fand keine belegten Quellen' : (text.length < 80 ? 'Antwort leer oder zu kurz' : 'keine Quellen-Adresse'))) + '), Paket ohne Recherche') };
}

// ---------- Teil 2: aktuelle Vorlagen (laeuft bei jedem Post) ----------
const v = nimm('Virale Posts Sonar [HTTP Request]');
const vMsg = (((Array.isArray(v.choices) ? v.choices : [])[0]) || {}).message || {};
const vText = String(vMsg.content || '').trim();
const vU = (v.usage && typeof v.usage === 'object') ? v.usage : {};
const vFehler = v.error ? String(v.error.message || v.error).slice(0, 160) : '';
// Warum Datumspruefung im Code: search_recency_filter week wirkt laut Messung (Hilfsaufrufe 781 gegen 782), trotzdem zaehlen nur Zeilen mit Datum in den letzten 8 Tagen (1 Tag Puffer fuer Zeitzonen).
const heute = Date.now();
const posts = [];
for (const zeile of vText.split('\n')) {
  const m = zeile.match(/^\s*-\s*POST:\s*(.*)$/i);
  if (!m) continue;
  const teile = m[1].split('|').map(s => s.trim());
  const datum = (teile.find(t => /^\d{4}-\d{2}-\d{2}$/.test(t)) || '');
  const url = (teile.find(t => /^https?:\/\/\S+$/.test(t)) || '');
  const hook = ((teile.find(t => /^Hook:/i.test(t)) || '').replace(/^Hook:\s*/i, '')).slice(0, 220);
  const tags = ((teile.find(t => /^Hashtags:/i.test(t)) || '').match(/#[\p{L}\p{N}_]+/gu) || []);
  const alter = datum ? (heute - Date.parse(datum + 'T12:00:00Z')) / 86400000 : 99;
  if (!url || !hook || !(alter >= -1 && alter <= 8)) continue;
  posts.push({ platform: teile[0].slice(0, 40), date: datum, url, hook, hashtags: tags });
}
// Warum nur Hashtags aus den Post-Zeilen: die Sammelzeile HASHTAGS koennte Erfundenes enthalten; gezaehlt wird nur, was an einem gefundenen Post steht.
const tagMap = new Map();
for (const p of posts) for (const t of p.hashtags) if (!tagMap.has(t.toLowerCase())) tagMap.set(t.toLowerCase(), t);
const vTags = Array.from(tagMap.values()).slice(0, 10);
const kw = ((vText.match(/^\s*KEYWORDS:\s*(.*)$/im) || [])[1] || '').split(',').map(s => s.trim()).filter(s => s && s.length <= 40).slice(0, 8);
let vStatus = 'ok';
if (vFehler || !vText) vStatus = 'fehler';
else if (!posts.length) vStatus = 'keine';
const vNote = vStatus === 'ok' ? '' : (vStatus === 'fehler' ? 'R2: Vorlagen-Recherche gescheitert (' + (vFehler || 'Antwort leer') + '), Hashtags ohne Vorlage' : 'R2: keine aktuellen englischen Posts der letzten 7 Tage gefunden, Hashtags ohne Vorlage');
const viralText = vStatus !== 'ok' ? '' : posts.map(p => '- ' + p.platform + ', ' + p.date + ': ' + p.hook + (p.hashtags.length ? ' (' + p.hashtags.join(' ') + ')' : '')).join('\n')
  + '\nHashtags aus diesen Posts: ' + (vTags.length ? vTags.join(' ') : 'keine') + '\nKeywords dieser Posts: ' + (kw.length ? kw.join(', ') : 'keine');
const kosten = [fakt.research_fact_cost_usd, zahl(vU.cost)].filter(x => x != null);

return [{ json: Object.assign({}, fakt, {
  viral_status: vStatus, viral_posts: posts, viral_hashtags: vTags, viral_keywords: kw, viral_text: viralText.slice(0, 1800), viral_note: vNote,
  viral_cost_usd: zahl(vU.cost),
  // Warum zusammengezaehlt: die Protokollzeile addiert research_cost_usd zu den Modellkosten, beide Sonar-Aufrufe zaehlen zum Lauf.
  research_cost_usd: kosten.length ? Math.round(kosten.reduce((a, b) => a + b, 0) * 1e7) / 1e7 : null
}), pairedItem: { item: 0 } }];
